package com.shale.data.dao;

import com.shale.core.dto.CaseTeamRoleDefinitionDto;
import com.shale.core.runtime.DbSessionProvider;
import com.shale.core.service.CaseServicePort.CaseTeamRoleCommand;
import com.shale.core.service.CaseServicePort.CaseTeamRoleLifecycleCommand;
import java.sql.*;
import java.util.*;
import static com.shale.data.dao.EntityActionAuditEvent.*;

/** Authoritative tenant-overlay administration for Case Team role definitions. */
public final class CaseTeamRoleDefinitionDao {
 private final DbSessionProvider db; private final EntityActionAuditDao audit=new EntityActionAuditDao();
 public CaseTeamRoleDefinitionDao(DbSessionProvider db){this.db=Objects.requireNonNull(db);}
 public List<CaseTeamRoleDefinitionDto> listForAdministration(int tenant,int actor){
  try(Connection c=db.requireConnection()){validateActor(c,tenant,actor); String sql="""
   WITH ranked AS (SELECT d.*,ROW_NUMBER() OVER(PARTITION BY d.SystemKey ORDER BY CASE WHEN d.ShaleClientId=? THEN 0 ELSE 1 END) rn
   FROM dbo.CaseTeamRoleDefinitions d WHERE d.SystemKey IS NOT NULL AND (d.ShaleClientId IS NULL OR d.ShaleClientId=?) AND (d.ShaleClientId IS NULL OR d.IsDeleted=0))
   SELECT * FROM ranked WHERE rn=1 UNION ALL SELECT d.*,1 rn FROM dbo.CaseTeamRoleDefinitions d WHERE d.ShaleClientId=? AND d.SystemKey IS NULL ORDER BY SortOrder,Name,Id""";
   try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,tenant);p.setInt(2,tenant);p.setInt(3,tenant);try(ResultSet r=p.executeQuery()){List<CaseTeamRoleDefinitionDto> out=new ArrayList<>();while(r.next())out.add(map(r,tenant));return out;}}
  }catch(SQLException e){throw failure("list",e);}
 }
 public CaseTeamRoleDefinitionDto create(CaseTeamRoleCommand x){return mutate(x.tenantId(),x.actorUserId(),c->{requireCreate(x);duplicate(c,x.tenantId(),x.name(),null);try(PreparedStatement p=c.prepareStatement("INSERT dbo.CaseTeamRoleDefinitions(ShaleClientId,Name,Description,Color,SortOrder,IsActive,IsProtected,CreatedByUserId) OUTPUT inserted.* VALUES(?,?,?,?,?,?,0,?)")){p.setInt(1,x.tenantId());bindText(p,2,x.name(),x.description(),x.color());p.setInt(5,x.sortOrder());p.setBoolean(6,x.active());p.setInt(7,x.actorUserId());try(ResultSet r=p.executeQuery()){r.next();var d=map(r,x.tenantId());append(c,x,d.id(),Action.CREATED);return d;}}});}
 public CaseTeamRoleDefinitionDto update(CaseTeamRoleCommand x){return mutate(x.tenantId(),x.actorUserId(),c->{requireVersion(x.rowVer());var source=find(c,x.id(),x.tenantId());if(!Arrays.equals(source.rowVer(),x.rowVer()))throw conflict();String key=source.systemKey();if(source.shaleClientId()==null){duplicate(c,x.tenantId(),x.name(),null);try(PreparedStatement p=c.prepareStatement("INSERT dbo.CaseTeamRoleDefinitions(ShaleClientId,SystemKey,LegacyRoleId,Name,Description,Color,SortOrder,IsActive,IsProtected,CreatedByUserId) OUTPUT inserted.* VALUES(?,?,?,?,?,?,?,?,0,?)")){p.setInt(1,x.tenantId());p.setString(2,key);if(source.legacyRoleId()==null)p.setNull(3,Types.INTEGER);else p.setInt(3,source.legacyRoleId());bindText(p,4,x.name(),x.description(),x.color());p.setInt(7,x.sortOrder());p.setBoolean(8,x.active());p.setInt(9,x.actorUserId());try(ResultSet r=p.executeQuery()){r.next();var d=map(r,x.tenantId());append(c,x,d.id(),Action.OVERRIDE_CREATED);return d;}}}
  duplicate(c,x.tenantId(),x.name(),x.id());try(PreparedStatement p=c.prepareStatement("UPDATE dbo.CaseTeamRoleDefinitions SET Name=?,Description=?,Color=?,SortOrder=?,IsActive=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? OUTPUT inserted.* WHERE Id=? AND ShaleClientId=? AND RowVer=? AND IsDeleted=0")){bindText(p,1,x.name(),x.description(),x.color());p.setInt(4,x.sortOrder());p.setBoolean(5,x.active());p.setInt(6,x.actorUserId());p.setInt(7,x.id());p.setInt(8,x.tenantId());p.setBytes(9,x.rowVer());try(ResultSet r=p.executeQuery()){if(!r.next())throw conflict();var d=map(r,x.tenantId());append(c,x,d.id(),x.active()==source.active()?Action.UPDATED:x.active()?Action.ACTIVATED:Action.DEACTIVATED);return d;}}});}
 public void lifecycle(CaseTeamRoleLifecycleCommand x, Action action){mutate(x.tenantId(),x.actorUserId(),c->{requireVersion(x.rowVer());var d=find(c,x.id(),x.tenantId());if(d.shaleClientId()==null||d.protectedSystemRole())throw new IllegalArgumentException("Protected system roles cannot be removed or restored directly.");String set=action==Action.REMOVED?"IsDeleted=1,IsActive=0,DeletedAt=SYSUTCDATETIME(),DeletedByUserId=?":"IsDeleted=0,DeletedAt=NULL,DeletedByUserId=NULL,IsActive=1";String sql="UPDATE dbo.CaseTeamRoleDefinitions SET "+set+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND RowVer=?";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;if(action==Action.REMOVED)p.setInt(i++,x.actorUserId());p.setInt(i++,x.actorUserId());p.setInt(i++,x.id());p.setInt(i++,x.tenantId());p.setBytes(i,x.rowVer());if(p.executeUpdate()!=1)throw conflict();append(c,x,x.id(),action);return null;}});}
 public void reset(CaseTeamRoleLifecycleCommand x){mutate(x.tenantId(),x.actorUserId(),c->{requireVersion(x.rowVer());var d=find(c,x.id(),x.tenantId());if(d.shaleClientId()==null||d.systemKey()==null)throw new IllegalArgumentException("Only a tenant override can be reset.");try(PreparedStatement p=c.prepareStatement("UPDATE dbo.CaseTeamRoleDefinitions SET IsDeleted=1,IsActive=0,DeletedAt=SYSUTCDATETIME(),DeletedByUserId=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND RowVer=?")){p.setInt(1,x.actorUserId());p.setInt(2,x.actorUserId());p.setInt(3,x.id());p.setInt(4,x.tenantId());p.setBytes(5,x.rowVer());if(p.executeUpdate()!=1)throw conflict();append(c,x,x.id(),Action.OVERRIDE_RESET);return null;}});}
 private <T>T mutate(int tenant,int actor,SqlWork<T>w){try(Connection c=db.requireConnection()){c.setAutoCommit(false);try{validateActor(c,tenant,actor);T result=w.run(c);c.commit();return result;}catch(Exception e){c.rollback();if(e instanceof RuntimeException re)throw re;throw (SQLException)e;}}catch(SQLException e){throw failure("mutate",e);}}
 private void validateActor(Connection c,int tenant,int actor)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT CAST(SESSION_CONTEXT(N'ShaleClientId') AS int),CAST(SESSION_CONTEXT(N'PrincipalUserId') AS int)" );ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)!=tenant||r.getInt(2)!=actor)throw new SecurityException("Requested tenant or actor does not match the authenticated session.");}try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo.Users WHERE id=? AND ShaleClientId=? AND ISNULL(is_admin,0)=1 AND ISNULL(is_deleted,0)=0")){p.setInt(1,actor);p.setInt(2,tenant);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SecurityException("Administrator authorization is required.");}}}
 private CaseTeamRoleDefinitionDto find(Connection c,int id,int tenant)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT * FROM dbo.CaseTeamRoleDefinitions WHERE Id=? AND (ShaleClientId IS NULL OR ShaleClientId=?)")){p.setInt(1,id);p.setInt(2,tenant);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Case Team role was not found.");return map(r,tenant);}}}
 private void duplicate(Connection c,int tenant,String name,Integer exclude)throws SQLException{String sql="SELECT 1 FROM dbo.CaseTeamRoleDefinitions d WHERE (d.ShaleClientId IS NULL OR d.ShaleClientId=?) AND d.IsDeleted=0 AND LOWER(LTRIM(RTRIM(d.Name)))=LOWER(LTRIM(RTRIM(?)))"+(exclude==null?"":" AND d.Id<>?");try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,tenant);p.setString(2,cleanName(name));if(exclude!=null)p.setInt(3,exclude);try(ResultSet r=p.executeQuery()){if(r.next())throw new IllegalArgumentException("A Case Team role with that name already exists.");}}}
 private void append(Connection c,Object cmd,long id,Action action)throws SQLException{int tenant=cmd instanceof CaseTeamRoleCommand x?x.tenantId():((CaseTeamRoleLifecycleCommand)cmd).tenantId();int actor=cmd instanceof CaseTeamRoleCommand x?x.actorUserId():((CaseTeamRoleLifecycleCommand)cmd).actorUserId();audit.append(c,EntityActionAuditEvent.now(tenant,actor,EntityType.CASE_TEAM_ROLE,id,action,null,null,Map.of(MetadataKey.DEFINITION_ID,id)));}
 private static CaseTeamRoleDefinitionDto map(ResultSet r,int tenant)throws SQLException{Integer owner=(Integer)r.getObject("ShaleClientId");Timestamp created=r.getTimestamp("CreatedAt"),updated=r.getTimestamp("UpdatedAt"),deleted=r.getTimestamp("DeletedAt");return new CaseTeamRoleDefinitionDto(r.getInt("Id"),owner,r.getString("SystemKey"),(Integer)r.getObject("LegacyRoleId"),r.getString("Name"),r.getString("Description"),r.getString("Color"),r.getInt("SortOrder"),r.getBoolean("IsActive"),r.getBoolean("IsDeleted"),r.getBoolean("IsProtected"),owner!=null&&r.getString("SystemKey")!=null,created.toInstant(),(Integer)r.getObject("CreatedByUserId"),updated==null?null:updated.toInstant(),(Integer)r.getObject("UpdatedByUserId"),deleted==null?null:deleted.toInstant(),(Integer)r.getObject("DeletedByUserId"),r.getBytes("RowVer"));}
 private static void requireCreate(CaseTeamRoleCommand x){if(x.id()!=null)throw new IllegalArgumentException("New roles cannot supply an id.");cleanName(x.name());cleanColor(x.color());}
 private static void requireVersion(byte[] v){if(v==null||v.length==0)throw new IllegalArgumentException("RowVer is required.");}
 private static String cleanName(String n){if(n==null||n.trim().isEmpty()||n.trim().length()>200)throw new IllegalArgumentException("Name is required and must be at most 200 characters.");return n.trim();}
 private static String cleanColor(String c){String v=c==null?"":c.trim().toUpperCase(Locale.ROOT);if(!v.matches("#[0-9A-F]{6}"))throw new IllegalArgumentException("Color must be #RRGGBB.");return v;}
 private static void bindText(PreparedStatement p,int i,String name,String description,String color)throws SQLException{p.setString(i,cleanName(name));p.setString(i+1,description==null||description.isBlank()?null:description.trim());p.setString(i+2,cleanColor(color));}
 private static IllegalStateException conflict(){return new IllegalStateException("Case Team role changed. Refresh and try again.");}
 private static RuntimeException failure(String op,SQLException e){return new RuntimeException("Failed to "+op+" Case Team roles",e);}
 @FunctionalInterface private interface SqlWork<T>{T run(Connection c)throws Exception;}
}
